parameters.functionCode:
const { severity, message, context, workflowName, timestamp } = $input.item.json;

const severityIcons = {
  info: '🔵',
  warning: '⚠️',
  error: '🔴'
};

const colors = {
  info: '#36a64f',
  warning: '#ff9900',
  error: '#ff0000'
};

let text = `${severityIcons[severity] || '🔵'} ${severity.toUpperCase()}: ${message}`;

if (workflowName) {
  text += `\n✉️ ${workflowName}`;
}

text += '\n───────────────';

if (context && Object.keys(context).length > 0) {
  for (const [key, value] of Object.entries(context)) {
    text += `\n${key}: ${value}`;
  }
}

return {
  slackPayload: {
    text,
    attachments: [{
      color: colors[severity] || colors.info,
      footer: `Sent at ${timestamp}`,
      ts: Math.floor(Date.now() / 1000)
    }]
  },
  channels: $input.item.json.channels
};

const { severity, message, context, workflowName, timestamp } = $('Set Input Parameters').item.json;

const subject = `[${severity.toUpperCase()}] ${message.substring(0, 50)}${message.length > 50 ? '...' : ''}${workflowName ? ' - ' + workflowName : ''}`;

let body = `Workflow: ${workflowName || 'N/A'}\n`;
body += `Severity: ${severity}\n`;
body += `Time: ${timestamp}\n\n`;
body += `Message:\n${message}\n\n`;

if (context && Object.keys(context).length > 0) {
  body += `Details:\n`;
  for (const [key, value] of Object.entries(context)) {
    body += `- ${key}: ${value}\n`;
  }
}

return {
  emailSubject: subject,
  emailBody: body,
  channels: $input.item.json.channels
};

// Collect results from both notification paths
const inputParams = $('Set Input Parameters').item.json;
const channels = inputParams.channels;

const deliveryResults = {};
const failedChannels = [];

// Check Slack result if attempted
if (channels.includes('slack')) {
  try {
    const slackNode = $('Send Slack Notification');
    if (slackNode) {
      const result = slackNode.item?.json;
      const success = result?.statusCode === 200 || result?.ok === 'ok';
      deliveryResults.slack = {
        success,
        timestamp: new Date().toISOString()
      };
      if (!success) failedChannels.push('slack');
    }
  } catch (e) {
    // Slack was not sent
  }
}

// Check Email result if attempted
if (channels.includes('email')) {
  try {
    const emailNode = $('Send Email Notification');
    if (emailNode) {
      const result = emailNode.item?.json;
      const success = !result?.error;
      deliveryResults.email = {
        success,
        timestamp: new Date().toISOString()
      };
      if (!success) failedChannels.push('email');
    }
  } catch (e) {
    // Email was not sent
  }
}

const notified = Object.values(deliveryResults).some(r => r.success);

return {
  notified,
  channels: Object.keys(deliveryResults),
  deliveryResults,
  failedChannels,
  originalMessage: inputParams.message,
  severity: inputParams.severity
};
